(()=>{"use strict";const{add,n,p,u,row:R,PI,rad}=CMModels,D=(s,name,purpose,f,calc,formula,e,note="Idealized classical model in SI units. Check sign conventions and assumptions; not a certified engineering design calculation.|\u4F7F\u7528 SI \u5355\u4F4D\u7684\u7406\u60F3\u7ECF\u5178\u6A21\u578B\uFF1B\u8BF7\u68C0\u67E5\u7B26\u53F7\u7EA6\u5B9A\u4E0E\u5047\u8BBE\uFF0C\u4E0D\u662F\u7ECF\u8BA4\u8BC1\u7684\u5DE5\u7A0B\u8BBE\u8BA1\u8BA1\u7B97\u3002")=>add(s,name,"Science",purpose,f,calc,formula,e,note),mass=n("m","Mass (kg)|\u8D28\u91CF\uFF08kg\uFF09",10),gravity=p("g","Gravity (m/s\xB2)|\u91CD\u529B\u52A0\u901F\u5EA6\uFF08m/s\xB2\uFF09",9.80665),speed=u("v","Velocity (m/s)|\u901F\u5EA6\uFF08m/s\uFF09",5),angle=n("a","Angle (degrees)|\u5939\u89D2\uFF08\u5EA6\uFF09",0,-360,360);D("force","Force from Mass and Acceleration|\u8D28\u91CF\u52A0\u901F\u5EA6\u6C42\u529B","Apply Newton\u2019s second law on one axis.|\u5728\u5355\u4E00\u8F74\u5411\u5E94\u7528\u725B\u987F\u7B2C\u4E8C\u5B9A\u5F8B\u3002",[mass,u("a","Acceleration (m/s\xB2)|\u52A0\u901F\u5EA6\uFF08m/s\xB2\uFF09",2)],v=>[R("Net force|\u5408\u529B",v.m*v.a,"N")],"F=ma",[20]),D("weight-force","Weight Force|\u91CD\u529B\u5927\u5C0F","Convert mass to weight under an entered gravitational field.|\u6309\u81EA\u586B\u91CD\u529B\u573A\u5C06\u8D28\u91CF\u8F6C\u6362\u4E3A\u91CD\u529B\u3002",[mass,gravity],v=>[R("Weight force|\u91CD\u529B",v.m*v.g,"N")],"W=mg",[98.0665]),D("momentum","Linear Momentum|\u7EBF\u52A8\u91CF","Calculate signed momentum along a single axis.|\u8BA1\u7B97\u5355\u4E00\u8F74\u5411\u5E26\u7B26\u53F7\u52A8\u91CF\u3002",[mass,speed],v=>[R("Momentum|\u52A8\u91CF",v.m*v.v,"kg\xB7m/s")],"p=mv",[50]),D("impulse","Impulse|\u51B2\u91CF","Calculate momentum change from a constant or average force.|\u7531\u6052\u529B\u6216\u5E73\u5747\u529B\u8BA1\u7B97\u52A8\u91CF\u53D8\u5316\u3002",[u("f","Average signed force (N)|\u5E73\u5747\u5E26\u7B26\u53F7\u529B\uFF08N\uFF09",20),n("t","Duration (s)|\u6301\u7EED\u65F6\u95F4\uFF08s\uFF09",3)],v=>[R("Impulse|\u51B2\u91CF",v.f*v.t,"N\xB7s")],"Use J = F\u0394t. F is average signed force in N and \u0394t is duration in s. Impulse J has units N\xB7s and equals the modeled signed change in momentum.|\u4F7F\u7528 J = F\u0394t\u3002F \u4E3A\u5E73\u5747\u5E26\u7B26\u53F7\u529B\uFF08N\uFF09\uFF0C\u0394t \u4E3A\u6301\u7EED\u65F6\u95F4\uFF08s\uFF09\uFF1B\u51B2\u91CF J \u7684\u5355\u4F4D\u4E3A N\xB7s\uFF0C\u7B49\u4E8E\u6A21\u578B\u4E2D\u7684\u5E26\u7B26\u53F7\u52A8\u91CF\u53D8\u5316\u3002",[60]),D("kinetic-energy","Kinetic Energy|\u52A8\u80FD","Find translational kinetic energy at nonrelativistic speed.|\u8BA1\u7B97\u975E\u76F8\u5BF9\u8BBA\u901F\u5EA6\u4E0B\u7684\u5E73\u52A8\u52A8\u80FD\u3002",[mass,speed],v=>[R("Kinetic energy|\u52A8\u80FD",.5*v.m*v.v*v.v,"J")],"Ek=\xBDmv\xB2",[125]),D("gravitational-potential-energy","Gravitational Potential Energy|\u91CD\u529B\u52BF\u80FD\u53D8\u5316","Calculate potential-energy change in a uniform gravitational field.|\u8BA1\u7B97\u5747\u5300\u91CD\u529B\u573A\u4E2D\u7684\u52BF\u80FD\u53D8\u5316\u3002",[mass,gravity,u("h","Height change (m)|\u9AD8\u5EA6\u53D8\u5316\uFF08m\uFF09",5)],v=>[R("Potential energy change|\u52BF\u80FD\u53D8\u5316",v.m*v.g*v.h,"J")],"\u0394U=mg\u0394h",[490.3325]),D("mechanical-work","Work by a Constant Force|\u6052\u529B\u505A\u529F","Find the component of constant force along displacement.|\u8BA1\u7B97\u6052\u529B\u6CBF\u4F4D\u79FB\u65B9\u5411\u6240\u505A\u7684\u529F\u3002",[n("f","Force magnitude (N)|\u529B\u5927\u5C0F\uFF08N\uFF09",20),n("s","Displacement magnitude (m)|\u4F4D\u79FB\u5927\u5C0F\uFF08m\uFF09",5),angle],v=>[R("Work|\u529F",v.f*v.s*Math.cos(rad(v.a)),"J")],"Use W = Fs cos\u03B8. F is force magnitude in N, s is displacement magnitude in m, and \u03B8 is the angle between them in degrees. Signed work W is in J.|\u4F7F\u7528 W = Fs cos\u03B8\u3002F \u4E3A\u529B\u5927\u5C0F\uFF08N\uFF09\uFF0Cs \u4E3A\u4F4D\u79FB\u5927\u5C0F\uFF08m\uFF09\uFF0C\u03B8 \u4E3A\u4E24\u8005\u5939\u89D2\uFF08\u5EA6\uFF09\uFF1B\u5E26\u7B26\u53F7\u529F W \u7684\u5355\u4F4D\u4E3A J\u3002",[100]),D("mechanical-power","Mechanical Power|\u673A\u68B0\u529F\u7387","Convert work over time to average mechanical power.|\u7531\u505A\u529F\u4E0E\u7528\u65F6\u8BA1\u7B97\u5E73\u5747\u673A\u68B0\u529F\u7387\u3002",[u("w","Work (J)|\u529F\uFF08J\uFF09",1e3),p("t","Duration (s)|\u7528\u65F6\uFF08s\uFF09",5)],v=>[R("Average power|\u5E73\u5747\u529F\u7387",v.w/v.t,"W")],"P=W/t",[200]),D("torque","Torque|\u529B\u77E9","Find torque magnitude from force, lever arm and included angle.|\u7531\u529B\u3001\u529B\u81C2\u957F\u5EA6\u4E0E\u5939\u89D2\u8BA1\u7B97\u529B\u77E9\u5927\u5C0F\u3002",[n("f","Force magnitude (N)|\u529B\u5927\u5C0F\uFF08N\uFF09",20),n("r","Radius to application point (m)|\u65BD\u529B\u70B9\u534A\u5F84\uFF08m\uFF09",.5),n("a","Included angle (degrees)|\u5939\u89D2\uFF08\u5EA6\uFF09",90,0,180)],v=>[R("Torque magnitude|\u529B\u77E9\u5927\u5C0F",v.f*v.r*Math.sin(rad(v.a)),"N\xB7m")],"Use \u03C4 = rF sin\u03B8. r is distance to the force application point in m, F is force magnitude in N, and \u03B8 is their included angle in degrees. Torque magnitude \u03C4 is in N\xB7m.|\u4F7F\u7528 \u03C4 = rF sin\u03B8\u3002r \u4E3A\u65BD\u529B\u70B9\u5230\u8F74\u5FC3\u8DDD\u79BB\uFF08m\uFF09\uFF0CF \u4E3A\u529B\u5927\u5C0F\uFF08N\uFF09\uFF0C\u03B8 \u4E3A\u4E24\u8005\u5939\u89D2\uFF08\u5EA6\uFF09\uFF1B\u529B\u77E9\u5927\u5C0F \u03C4 \u7684\u5355\u4F4D\u4E3A N\xB7m\u3002",[10]),D("lever-equilibrium","Lever Equilibrium|\u6760\u6746\u5E73\u8861","Solve a perpendicular balancing force around a pivot.|\u6C42\u652F\u70B9\u4E24\u4FA7\u5782\u76F4\u65BD\u529B\u7684\u5E73\u8861\u529B\u3002",[n("f","Known force (N)|\u5DF2\u77E5\u529B\uFF08N\uFF09",100),p("a","Known lever arm (m)|\u5DF2\u77E5\u529B\u81C2\uFF08m\uFF09",.5),p("b","Opposite lever arm (m)|\u53E6\u4E00\u529B\u81C2\uFF08m\uFF09",2)],v=>[R("Balancing force|\u5E73\u8861\u529B",v.f*v.a/v.b,"N")],"F\u2081L\u2081=F\u2082L\u2082",[25]),D("hookes-law","Hooke\u2019s Law Spring Force|\u80E1\u514B\u5B9A\u5F8B\u5F39\u7C27\u529B","Calculate restoring force for a linear elastic spring.|\u8BA1\u7B97\u7EBF\u6027\u5F39\u6027\u5F39\u7C27\u7684\u56DE\u590D\u529B\u3002",[n("k","Spring stiffness (N/m)|\u5F39\u7C27\u521A\u5EA6\uFF08N/m\uFF09",200),u("x","Displacement from equilibrium (m)|\u76F8\u5BF9\u5E73\u8861\u4F4D\u7F6E\u4F4D\u79FB\uFF08m\uFF09",.1)],v=>[R("Restoring force|\u56DE\u590D\u529B",-v.k*v.x,"N")],"F=\u2212kx",[-20],"Linear elastic range only; sign is opposite displacement. Plastic deformation and spring mass are omitted.|\u4EC5\u9650\u7EBF\u5F39\u6027\u8303\u56F4\uFF0C\u529B\u65B9\u5411\u4E0E\u4F4D\u79FB\u76F8\u53CD\uFF1B\u5FFD\u7565\u5851\u6027\u53D8\u5F62\u4E0E\u5F39\u7C27\u8D28\u91CF\u3002"),D("spring-energy","Elastic Spring Energy|\u5F39\u7C27\u5F39\u6027\u52BF\u80FD","Find stored energy in an ideal linear spring.|\u8BA1\u7B97\u7406\u60F3\u7EBF\u6027\u5F39\u7C27\u7684\u50A8\u80FD\u3002",[n("k","Spring stiffness (N/m)|\u5F39\u7C27\u521A\u5EA6\uFF08N/m\uFF09",200),u("x","Extension or compression (m)|\u4F38\u957F\u6216\u538B\u7F29\u91CF\uFF08m\uFF09",.1)],v=>[R("Stored elastic energy|\u50A8\u5B58\u5F39\u6027\u52BF\u80FD",.5*v.k*v.x*v.x,"J")],"U=\xBDkx\xB2",[1]),D("friction-force","Friction Force|\u6469\u64E6\u529B","Compare kinetic friction with the maximum static-friction limit.|\u6BD4\u8F83\u52A8\u6469\u64E6\u529B\u4E0E\u6700\u5927\u9759\u6469\u64E6\u754C\u9650\u3002",[n("n","Normal force (N)|\u6CD5\u5411\u529B\uFF08N\uFF09",100),n("k","Kinetic coefficient|\u52A8\u6469\u64E6\u7CFB\u6570",.3,0,10),n("s","Static coefficient|\u9759\u6469\u64E6\u7CFB\u6570",.5,0,10)],v=>[R("Kinetic friction magnitude|\u52A8\u6469\u64E6\u529B\u5927\u5C0F",v.n*v.k,"N"),R("Maximum static friction|\u6700\u5927\u9759\u6469\u64E6\u529B",v.n*v.s,"N")],"Fk=\u03BCkN; |Fs|\u2264\u03BCsN",[30,50],"Static friction adjusts up to its limit; the maximum is not automatically the actual force.|\u9759\u6469\u64E6\u529B\u4F1A\u8C03\u6574\u81F3\u6240\u9700\u503C\uFF0C\u4F46\u4E0D\u8D85\u8FC7\u4E0A\u9650\uFF1B\u6700\u5927\u503C\u4E0D\u81EA\u52A8\u7B49\u4E8E\u5B9E\u9645\u529B\u3002"),D("centripetal-force","Centripetal Force|\u5411\u5FC3\u529B","Find inward force and acceleration for circular motion.|\u6C42\u5706\u5468\u8FD0\u52A8\u7684\u5411\u5FC3\u529B\u4E0E\u5411\u5FC3\u52A0\u901F\u5EA6\u3002",[mass,n("v","Tangential speed (m/s)|\u5207\u5411\u901F\u7387\uFF08m/s\uFF09",5),p("r","Radius (m)|\u534A\u5F84\uFF08m\uFF09",2)],v=>[R("Inward net force|\u5411\u5FC3\u5408\u529B",v.m*v.v*v.v/v.r,"N"),R("Centripetal acceleration|\u5411\u5FC3\u52A0\u901F\u5EA6",v.v*v.v/v.r,"m/s\xB2")],"F=mv\xB2/r; a=v\xB2/r",[125,12.5]),D("angular-velocity","Angular Velocity|\u89D2\u901F\u5EA6","Convert rotation frequency into angular and rim speed.|\u7531\u8F6C\u52A8\u9891\u7387\u6C42\u89D2\u901F\u5EA6\u4E0E\u8FB9\u7F18\u7EBF\u901F\u5EA6\u3002",[u("f","Rotations per minute|\u6BCF\u5206\u949F\u8F6C\u6570",60),n("r","Radius (m)|\u534A\u5F84\uFF08m\uFF09",.5)],v=>[R("Angular velocity|\u89D2\u901F\u5EA6",v.f*2*PI/60,"rad/s"),R("Rim velocity|\u8FB9\u7F18\u7EBF\u901F\u5EA6",v.f*2*PI/60*v.r,"m/s")],"Use \u03C9 = 2\u03C0n/60 and v = \u03C9r. n is rotations per minute and r is radius in m. Angular speed \u03C9 is in rad/s and tangential speed v is in m/s.|\u4F7F\u7528 \u03C9 = 2\u03C0n/60 \u53CA v = \u03C9r\u3002n \u4E3A\u6BCF\u5206\u949F\u8F6C\u6570\uFF0Cr \u4E3A\u534A\u5F84\uFF08m\uFF09\uFF1B\u89D2\u901F\u7387 \u03C9 \u7684\u5355\u4F4D\u4E3A rad/s\uFF0C\u5207\u5411\u901F\u7387 v \u7684\u5355\u4F4D\u4E3A m/s\u3002",[2*PI,PI]),D("angular-acceleration","Angular Acceleration|\u89D2\u52A0\u901F\u5EA6","Find average angular acceleration between two velocities.|\u7531\u4E24\u4E2A\u89D2\u901F\u5EA6\u6C42\u5E73\u5747\u89D2\u52A0\u901F\u5EA6\u3002",[u("a","Initial angular velocity (rad/s)|\u521D\u59CB\u89D2\u901F\u5EA6\uFF08rad/s\uFF09",2),u("b","Final angular velocity (rad/s)|\u6700\u7EC8\u89D2\u901F\u5EA6\uFF08rad/s\uFF09",10),p("t","Elapsed time (s)|\u7ECF\u8FC7\u65F6\u95F4\uFF08s\uFF09",4)],v=>[R("Average angular acceleration|\u5E73\u5747\u89D2\u52A0\u901F\u5EA6",(v.b-v.a)/v.t,"rad/s\xB2")],"\u03B1=(\u03C9\u2081\u2212\u03C9\u2080)/\u0394t",[2]),D("rotational-energy","Rotational Kinetic Energy|\u8F6C\u52A8\u52A8\u80FD","Calculate rotation energy from moment of inertia and angular velocity.|\u7531\u8F6C\u52A8\u60EF\u91CF\u4E0E\u89D2\u901F\u5EA6\u8BA1\u7B97\u8F6C\u52A8\u52A8\u80FD\u3002",[n("i","Moment of inertia (kg\xB7m\xB2)|\u8F6C\u52A8\u60EF\u91CF\uFF08kg\xB7m\xB2\uFF09",2),u("w","Angular velocity (rad/s)|\u89D2\u901F\u5EA6\uFF08rad/s\uFF09",10)],v=>[R("Rotational energy|\u8F6C\u52A8\u52A8\u80FD",.5*v.i*v.w*v.w,"J")],"E=\xBDI\u03C9\xB2",[100]),D("disk-moment-of-inertia","Disk Moment of Inertia|\u5706\u76D8\u8F6C\u52A8\u60EF\u91CF","Find inertia of a uniform solid disk about its central normal axis.|\u8BA1\u7B97\u5747\u5300\u5B9E\u5FC3\u5706\u76D8\u7ED5\u4E2D\u5FC3\u5782\u76F4\u8F74\u7684\u8F6C\u52A8\u60EF\u91CF\u3002",[mass,n("r","Disk radius (m)|\u5706\u76D8\u534A\u5F84\uFF08m\uFF09",.5)],v=>[R("Moment of inertia|\u8F6C\u52A8\u60EF\u91CF",.5*v.m*v.r*v.r,"kg\xB7m\xB2")],"I=\xBDmr\xB2",[1.25]),D("projectile-range","Projectile Range|\u629B\u4F53\u5C04\u7A0B","Model ideal flight landing at the launch height.|\u8BA1\u7B97\u843D\u70B9\u4E0E\u8D77\u70B9\u7B49\u9AD8\u7684\u7406\u60F3\u629B\u4F53\u8FD0\u52A8\u3002",[n("v","Launch speed (m/s)|\u53D1\u5C04\u901F\u7387\uFF08m/s\uFF09",20),n("a","Launch elevation (degrees)|\u4EF0\u89D2\uFF08\u5EA6\uFF09",45,0,90),gravity],v=>[R("Horizontal range|\u6C34\u5E73\u5C04\u7A0B",v.v*v.v*Math.sin(2*rad(v.a))/v.g,"m"),R("Flight time|\u98DE\u884C\u65F6\u95F4",2*v.v*Math.sin(rad(v.a))/v.g,"s"),R("Maximum rise|\u6700\u9AD8\u4E0A\u5347\u9AD8\u5EA6",(v.v*Math.sin(rad(v.a)))**2/(2*v.g),"m")],"Use R = v\xB2sin(2\u03B8)/g and t = 2v sin\u03B8/g. v is launch speed in m/s, \u03B8 is elevation in degrees, and g is gravity in m/s\xB2. Range R is in m and flight time t is in s, with equal launch and landing heights and no air resistance.|\u4F7F\u7528 R = v\xB2sin(2\u03B8)/g \u53CA t = 2v sin\u03B8/g\u3002v \u4E3A\u53D1\u5C04\u901F\u7387\uFF08m/s\uFF09\uFF0C\u03B8 \u4E3A\u4EF0\u89D2\uFF08\u5EA6\uFF09\uFF0Cg \u4E3A\u91CD\u529B\u52A0\u901F\u5EA6\uFF08m/s\xB2\uFF09\uFF1B\u5C04\u7A0B R \u7684\u5355\u4F4D\u4E3A m\uFF0C\u98DE\u884C\u65F6\u95F4 t \u7684\u5355\u4F4D\u4E3A s\uFF0C\u5047\u8BBE\u8D77\u843D\u7B49\u9AD8\u4E14\u65E0\u7A7A\u6C14\u963B\u529B\u3002",[400/9.80665,20*Math.SQRT2/9.80665,100/9.80665],"Same launch and landing height, constant gravity, no drag, wind or Earth curvature.|\u8D77\u843D\u7B49\u9AD8\u3001\u91CD\u529B\u6052\u5B9A\uFF0C\u5FFD\u7565\u963B\u529B\u3001\u98CE\u4E0E\u5730\u7403\u66F2\u7387\u3002"),D("free-fall","Free Fall from Rest|\u9759\u6B62\u81EA\u7531\u843D\u4F53","Estimate fall time and impact speed from a release height.|\u7531\u91CA\u653E\u9AD8\u5EA6\u4F30\u8BA1\u81EA\u7531\u843D\u4F53\u65F6\u95F4\u4E0E\u89E6\u5730\u901F\u7387\u3002",[n("h","Release height (m)|\u91CA\u653E\u9AD8\u5EA6\uFF08m\uFF09",20),gravity],v=>[R("Fall time|\u4E0B\u843D\u65F6\u95F4",Math.sqrt(2*v.h/v.g),"s"),R("Impact speed magnitude|\u89E6\u5730\u901F\u7387",Math.sqrt(2*v.g*v.h),"m/s")],"Use t = \u221A(2h/g) and v = \u221A(2gh). h is release height in m and g is gravity in m/s\xB2. Time t is in s and speed v is in m/s, starting from rest without air resistance.|\u4F7F\u7528 t = \u221A(2h/g) \u53CA v = \u221A(2gh)\u3002h \u4E3A\u91CA\u653E\u9AD8\u5EA6\uFF08m\uFF09\uFF0Cg \u4E3A\u91CD\u529B\u52A0\u901F\u5EA6\uFF08m/s\xB2\uFF09\uFF1B\u65F6\u95F4 t \u7684\u5355\u4F4D\u4E3A s\uFF0C\u901F\u7387 v \u7684\u5355\u4F4D\u4E3A m/s\uFF0C\u5047\u8BBE\u7531\u9759\u6B62\u91CA\u653E\u4E14\u65E0\u7A7A\u6C14\u963B\u529B\u3002",[Math.sqrt(40/9.80665),Math.sqrt(40*9.80665)],"Released from rest in uniform gravity, without drag. Not a fall-safety assessment.|\u5747\u5300\u91CD\u529B\u4E0B\u4ECE\u9759\u6B62\u91CA\u653E\u4E14\u5FFD\u7565\u963B\u529B\uFF0C\u4E0D\u7528\u4E8E\u5760\u843D\u5B89\u5168\u8BC4\u4F30\u3002"),D("escape-velocity","Escape Velocity|\u9003\u9038\u901F\u5EA6","Estimate escape speed from a spherical gravitating body.|\u4F30\u7B97\u7403\u5F62\u5929\u4F53\u8868\u9762\u7684\u9003\u9038\u901F\u5EA6\u3002",[n("m","Central mass (kg)|\u4E2D\u5FC3\u5929\u4F53\u8D28\u91CF\uFF08kg\uFF09",5972e21,1,1e40),p("r","Distance from centre (m)|\u8DDD\u4E2D\u5FC3\u8DDD\u79BB\uFF08m\uFF09",6371e3)],v=>[R("Escape speed|\u9003\u9038\u901F\u5EA6",Math.sqrt(2*66743e-15*v.m/v.r),"m/s")],"v=\u221A(2GM/r)",[Math.sqrt(2*66743e-15*5972e21/6371e3)],"Newtonian isolated spherical body; excludes atmosphere, rotation and other bodies. G=6.67430\xD710\u207B\xB9\xB9 SI.|\u725B\u987F\u5B64\u7ACB\u7403\u5F62\u5929\u4F53\u6A21\u578B\uFF0C\u5FFD\u7565\u5927\u6C14\u3001\u81EA\u8F6C\u4E0E\u5176\u4ED6\u5929\u4F53\uFF1BG=6.67430\xD710\u207B\xB9\xB9\uFF08SI\uFF09\u3002"),D("universal-gravitation","Universal Gravitation|\u4E07\u6709\u5F15\u529B","Calculate mutual gravitational attraction between point masses.|\u8BA1\u7B97\u70B9\u8D28\u91CF\u95F4\u7684\u4E07\u6709\u5F15\u529B\u3002",[n("a","Mass A (kg)|\u8D28\u91CF A\uFF08kg\uFF09",1e3),n("b","Mass B (kg)|\u8D28\u91CF B\uFF08kg\uFF09",1e3),p("r","Centre-to-centre separation (m)|\u8D28\u5FC3\u95F4\u8DDD\u79BB\uFF08m\uFF09",1)],v=>[R("Attractive force|\u5F15\u529B\u5927\u5C0F",66743e-15*v.a*v.b/v.r**2,"N")],"F=Gm\u2081m\u2082/r\xB2",[66743e-9]),D("pendulum-period","Simple Pendulum Period|\u5355\u6446\u5468\u671F","Estimate the small-angle period of an ideal pendulum.|\u4F30\u8BA1\u7406\u60F3\u5355\u6446\u7684\u5C0F\u89D2\u5EA6\u5468\u671F\u3002",[n("l","Pendulum length (m)|\u6446\u957F\uFF08m\uFF09",1),gravity],v=>[R("Small-angle period|\u5C0F\u89D2\u5EA6\u5468\u671F",2*PI*Math.sqrt(v.l/v.g),"s")],"T=2\u03C0\u221A(L/g)",[2*PI/Math.sqrt(9.80665)],"Small amplitude, massless string, point bob, fixed pivot and no friction.|\u5C0F\u632F\u5E45\u3001\u65E0\u8D28\u91CF\u7EC6\u7EF3\u3001\u8D28\u70B9\u6446\u7403\u3001\u56FA\u5B9A\u652F\u70B9\u4E14\u65E0\u6469\u64E6\u3002"),D("spring-oscillation-period","Spring Oscillation Period|\u5F39\u7C27\u632F\u5B50\u5468\u671F","Find an ideal mass-spring system\u2019s natural period.|\u8BA1\u7B97\u7406\u60F3\u8D28\u70B9\u5F39\u7C27\u7CFB\u7EDF\u7684\u56FA\u6709\u5468\u671F\u3002",[mass,p("k","Spring stiffness (N/m)|\u5F39\u7C27\u521A\u5EA6\uFF08N/m\uFF09",200)],v=>[R("Natural period|\u56FA\u6709\u5468\u671F",2*PI*Math.sqrt(v.m/v.k),"s"),R("Natural frequency|\u56FA\u6709\u9891\u7387",Math.sqrt(v.k/v.m)/(2*PI),"Hz")],"T=2\u03C0\u221A(m/k)",[2*PI/Math.sqrt(20),Math.sqrt(20)/(2*PI)]),D("elastic-collision","One Dimensional Elastic Collision|\u4E00\u7EF4\u5F39\u6027\u78B0\u649E","Solve final velocities for an isolated perfectly elastic collision.|\u6C42\u5B64\u7ACB\u7CFB\u7EDF\u5B8C\u5168\u5F39\u6027\u78B0\u649E\u540E\u7684\u901F\u5EA6\u3002",[p("a","Mass A (kg)|\u8D28\u91CF A\uFF08kg\uFF09",2),p("b","Mass B (kg)|\u8D28\u91CF B\uFF08kg\uFF09",2),u("u","Initial A velocity (m/s)|A \u521D\u901F\u5EA6\uFF08m/s\uFF09",5),u("v","Initial B velocity (m/s)|B \u521D\u901F\u5EA6\uFF08m/s\uFF09",0)],v=>[R("Final A velocity|A \u672B\u901F\u5EA6",((v.a-v.b)*v.u+2*v.b*v.v)/(v.a+v.b),"m/s"),R("Final B velocity|B \u672B\u901F\u5EA6",(2*v.a*v.u+(v.b-v.a)*v.v)/(v.a+v.b),"m/s")],"Use v\u2090 = [(m\u2090\u2212m\u1D66)u\u2090+2m\u1D66u\u1D66]/(m\u2090+m\u1D66) and v\u1D66 = [2m\u2090u\u2090+(m\u1D66\u2212m\u2090)u\u1D66]/(m\u2090+m\u1D66). m denotes mass, u initial signed velocity, and v final signed velocity; subscripts distinguish the bodies. Use consistent mass and velocity units.|\u4F7F\u7528 v\u2090 = [(m\u2090\u2212m\u1D66)u\u2090+2m\u1D66u\u1D66]/(m\u2090+m\u1D66) \u53CA v\u1D66 = [2m\u2090u\u2090+(m\u1D66\u2212m\u2090)u\u1D66]/(m\u2090+m\u1D66)\u3002m \u8868\u793A\u8D28\u91CF\uFF0Cu \u8868\u793A\u521D\u59CB\u5E26\u7B26\u53F7\u901F\u5EA6\uFF0Cv \u8868\u793A\u6700\u7EC8\u5E26\u7B26\u53F7\u901F\u5EA6\uFF0C\u4E0B\u6807\u533A\u5206\u7269\u4F53\uFF1B\u8D28\u91CF\u548C\u901F\u5EA6\u5206\u522B\u4F7F\u7528\u4E00\u81F4\u5355\u4F4D\u3002",[0,5])})();
